{{ config(
            materialized='table',
                post_hook={
                    "sql": "CREATE OR REPLACE TABLE snitch_db.maplemonk.rto_report AS WITH ranked_data AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date, ROW_NUMBER() OVER ( PARTITION BY \"Sale Order Item\" ORDER BY TO_TIMESTAMP(\"Return Date\", \'YYYY-MM-DD HH24:MI:SS\') DESC ) AS row_num FROM snitch_db.maplemonk.snitch_db_get_courier_returns_itemwise_new WHERE \"Return Date\"::date >= \'2024-10-01\' ) SELECT * FROM ranked_data WHERE row_num = 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.dto_report AS WITH ranked_data AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date, ROW_NUMBER() OVER ( PARTITION BY \"Sale Order Item Code\" ORDER BY TO_TIMESTAMP(\"Reverse Pickup Last Updated\", \'YYYY-MM-DD HH24:MI:SS\') DESC ) AS row_num FROM snitch_db.maplemonk.snitch_get_copy_of_reverse_pickup WHERE \"Reverse Pickup Last Updated\"::date >= \'2024-10-01\' AND \"Warehouse Name\" LIKE \'%WH%\' ) SELECT * FROM ranked_data WHERE row_num = 1; CREATE OR REPLACE TABLE snitch_db.maplemonk.manifest_report AS WITH shipping_manifest AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date FROM snitch_db.maplemonk.unicommerce_get_shipping_manifest_by_item WHERE CAST(created AS DATE) >= \'2024-11-01\' and \"Warehouse Name\" like \'%WH%\' ), ranked_manifest AS ( SELECT sm.*, u.marketplace_mapped, u.order_timestamp, ROW_NUMBER() OVER ( PARTITION BY CONCAT(sm.\"Order Number\", sm.\"Shipping Package Code\") ORDER BY sm.UPDATED DESC ) AS row_num FROM shipping_manifest AS sm LEFT JOIN snitch_db.maplemonk.unicommerce_fact_items_intermediate AS u ON sm.\"Order Number\" = u.order_name AND CAST(u.order_timestamp AS DATE) >= \'2024-10-15\' ) SELECT * FROM ranked_manifest WHERE row_num = 1 ; CREATE OR REPLACE TABLE snitch_db.maplemonk.picklist_report AS WITH picklist_cte AS ( SELECT *, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) BETWEEN 8 AND 19 THEN \'Day\' ELSE \'Night\' END AS shift_type, CASE WHEN EXTRACT(HOUR FROM TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\')) < 8 THEN DATEADD(DAY, -1, CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE)) ELSE CAST(TO_TIMESTAMP(UPDATED, \'YYYY-MM-DD HH24:MI:SS\') AS DATE) END AS adjusted_date FROM snitch_db.maplemonk.unicommerce_get_picklist WHERE created >= \'2024-11-01\' AND \"Warehouse Name\" LIKE \'%WH%\' ), intermediate AS ( SELECT order_id, order_timestamp, marketplace_mapped FROM snitch_db.maplemonk.unicommerce_fact_items_intermediate WHERE order_date >= \'2024-10-21\' ), ranked_data AS ( SELECT p.*, i.marketplace_mapped, i.order_timestamp, ROW_NUMBER() OVER ( PARTITION BY p.\"Sale Order Item Code\", p.\"Picklist Code\", p.\"Item Status\" ORDER BY p.UPDATED DESC ) AS row_num FROM picklist_cte AS p LEFT JOIN intermediate AS i ON p.\"Sale Order Code\" = i.order_id ) SELECT * FROM ranked_data WHERE row_num = 1;",
                    "transaction": true
                }
            ) }}
